// Normalize the incoming domain and fan out one DNS query per record type,
// plus the _dmarc TXT record used for email authentication.
const raw = String($input.first().json.body?.domain ?? '').trim().toLowerCase();
const domain = raw.replace(/^[a-z]+:\/\//, '').split('/')[0].split(':')[0].replace(/\.$/, '');
const queries = ['A', 'AAAA', 'CNAME', 'NS', 'MX', 'TXT'].map(type => ({ json: { domain, type, key: type } }));
queries.push({ json: { domain: '_dmarc.' + domain, type: 'TXT', key: 'DMARC' } });
return queries;

// Combine the per-type DNS answers into one compact result for Domain Guard.
const TYPE_NAMES = { 1: 'A', 28: 'AAAA', 5: 'CNAME', 2: 'NS', 15: 'MX', 16: 'TXT' };
const STATUS_NAMES = { 0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 5: 'REFUSED' };
const queries = $('Build queries').all();
const domain = queries[0]?.json.domain ?? '';
const records = { A: [], AAAA: [], CNAME: [], NS: [], MX: [], TXT: [] };
const dmarcRecords = [];
const statuses = [];
const errors = [];
const unquote = (s) => String(s).replace(/^"|"$/g, '').replace(/"\s*"/g, '');

$input.all().forEach((item, i) => {
  const { type, key } = queries[i]?.json ?? {};
  const j = item.json;
  if (j.error) {
    const e = j.error;
    errors.push(key + ': ' + (typeof e === 'string' ? e : (e.message || JSON.stringify(e))));
    return;
  }
  // A missing _dmarc record is normal NXDOMAIN and says nothing about the domain itself.
  if (key !== 'DMARC') statuses.push(STATUS_NAMES[j.Status] ?? String(j.Status));
  for (const a of j.Answer || []) {
    if (key === 'DMARC') {
      if (a.type === 16) dmarcRecords.push(unquote(a.data));
      continue;
    }
    const t = TYPE_NAMES[a.type];
    const value = t === 'TXT' ? unquote(a.data) : a.data;
    if (t && !records[t].includes(value)) records[t].push(value);
  }
});

let dns_status = 'UNKNOWN';
if (statuses.includes('NXDOMAIN')) dns_status = 'NXDOMAIN';
else if (statuses.length && statuses.every(s => s === 'NOERROR')) dns_status = 'NOERROR';
else if (statuses.length) dns_status = statuses.find(s => s !== 'NOERROR');

// Email authentication: SPF lives in the domain's TXT records, DMARC at _dmarc.
const spf = records.TXT.filter(t => /^v=spf1(\s|$)/i.test(t));
const dmarc = dmarcRecords.filter(t => /^v=DMARC1/i.test(t));
const receivesMail = records.MX.length > 0 && !records.MX.every(m => /^0 \.?$/.test(m));
const warnings = [];
if (spf.length > 1) warnings.push('multiple_spf_records');
if (dmarc.length > 1) warnings.push('multiple_dmarc_records');
if (receivesMail && spf.length === 0) warnings.push('mx_without_spf');
if (receivesMail && dmarc.length === 0) warnings.push('mx_without_dmarc');

return [{ json: {
  domain,
  resolves: records.A.length > 0 || records.AAAA.length > 0,
  dns_status,
  records,
  email: {
    receives_mail: receivesMail,
    spf: spf[0] ?? null,
    dmarc: dmarc[0] ?? null,
    dmarc_policy: (dmarc[0]?.match(/;\s*p=(\w+)/i) || [])[1] ?? null,
    warnings,
  },
  resolver: 'dns.google',
  errors,
} }];
